text:
{
  "units": {
    "s001": {
      "claims": [
        {
          "claim": "该2025级学生在2026年秋季辅修申请所在学期从理工科转到文科。",
          "evidence_sentence_ids": [],
          "score": 2,
          "verdict": "unsupported"
        }
      ],
      "non_factual_reason": "无证据支持该学生实际转专业行为，仅在答案中陈述，未在证据中体现具体转专业事实。"
    },
    "s002": {
      "claims": [
        {
          "claim": "根据《2026年秋季学期辅修申请通知》[1]中的规定：",
          "evidence_sentence_ids": [
            "b1_s008"
          ],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": ""
    },
    "s003": {
      "claims": [
        {
          "claim": "文科类学生前一学期平均学分绩点达到3.0及以上。",
          "evidence_sentence_ids": [
            "b1_s012"
          ],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": ""
    },
    "s004": {
      "claims": [
        {
          "claim": "理工科类学生前一学期平均学分绩点达到2.8及以上。",
          "evidence_sentence_ids": [
            "b1_s013"
          ],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": ""
    },
    "s005": {
      "claims": [
        {
          "claim": "本学期有过转专业记录的学生，按前一学期所在专业匹配限制条件。",
          "evidence_sentence_ids": [
            "b1_s014"
          ],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": ""
    },
    "s006": {
      "claims": [
        {
          "claim": "该学生前一学期属于理工科专业，因此应按理工科类学生的绩点标准进行审核，即要求前一学期平均学分绩点达到2.8及以上。",
          "evidence_sentence_ids": [
            "b1_s014",
            "b1_s013"
          ],
          "score": 4,
          "verdict": "partially_supported"
        }
      ],
      "non_factual_reason": "证据未明确说明该学生前一学期专业类别为理工科，仅通过答案推断，缺乏直接事实支持。"
    },
    "s007": {
      "claims": [
        {
          "claim": "该学生前一学期GPA为2.9，高于2.8，满足理工科类学生的绩点要求。",
          "evidence_sentence_ids": [
            "b1_s012",
            "b1_s013"
          ],
          "score": 4,
          "verdict": "partially_supported"
        }
      ],
      "non_factual_reason": "GPA为2.9在证据中未直接陈述，仅在s001中提及，未在证据中明确列出。"
    },
    "s008": {
      "claims": [
        {
          "claim": "因此，该学生在绩点方面满足辅修资格的条件。",
          "evidence_sentence_ids": [],
          "score": 2,
          "verdict": "unsupported"
        }
      ],
      "non_factual_reason": "该结论基于对绩点标准满足的推导，但无证据直接支持其满足资格条件。"
    },
    "s009": {
      "claims": [
        {
          "claim": "该学生在辅修申请学期‘有过转专业记录’，根据通知规定，按前一学期所在专业匹配限制条件，即仍以前一学期专业类别为准，而非当前专业类别。",
          "evidence_sentence_ids": [
            "b1_s014"
          ],
          "score": 4,
          "verdict": "partially_supported"
        }
      ],
      "non_factual_reason": "‘有过转专业记录’在证据中未明确提及，仅规定了匹配规则，未证实该学生有此记录。"
    },
    "s010": {
      "claims": [
        {
          "claim": "因此，其绩点标准仍应按其前一学期所在专业（理工科）的2.8标准执行。",
          "evidence_sentence_ids": [
            "b1_s014",
            "b1_s013"
          ],
          "score": 4,
          "verdict": "partially_supported"
        }
      ],
      "non_factual_reason": "‘理工科’专业类别未在证据中明确确认，仅通过答案推断。"
    },
    "s011": {
      "claims": [
        {
          "claim": "综上，该学生满足绩点审核要求，能保证在绩点方面通过资格审核。",
          "evidence_sentence_ids": [],
          "score": 2,
          "verdict": "unsupported"
        }
      ],
      "non_factual_reason": "无证据支持‘能保证通过’，仅基于标准满足推导，未被证据直接或间接证实。"
    },
    "s012": {
      "claims": [
        {
          "claim": "该学生应按理工科类学生前一学期平均学分绩点2.8及以上标准审核，其GPA为2.9，满足该标准，能保证在绩点方面通过审核。",
          "evidence_sentence_ids": [
            "b1_s013",
            "b1_s014"
          ],
          "score": 3,
          "verdict": "partially_supported"
        }
      ],
      "non_factual_reason": "‘能保证通过’属于过度推断，未在证据中体现‘保证’或‘无例外’条件。"
    },
    "s013": {
      "claims": [
        {
          "claim": "但是否最终被选中，还需结合辅修学院的择优选拔、名额限制及公示程序等环节，仅凭绩点无法保证最终被录取。",
          "evidence_sentence_ids": [
            "b4_s008",
            "b4_s009"
          ],
          "score": 4,
          "verdict": "partially_supported"
        }
      ],
      "non_factual_reason": "证据提及审核流程，但未明确说明‘最终被选中’需择优选拔，该陈述为合理推断但非直接支持。"
    }
  }
}
